CREATE TABLE IF NOT EXISTS course_commerce (course_id VARCHAR(40) PRIMARY KEY, price_minor INTEGER NOT NULL DEFAULT 0, enrollment_open INTEGER NOT NULL DEFAULT 0, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS learning_bags (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, version VARCHAR(50) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS bag_items (id VARCHAR(40) PRIMARY KEY, bag_id VARCHAR(40) NOT NULL, file_id VARCHAR(40) NOT NULL, label VARCHAR(200) NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, UNIQUE(bag_id,file_id), FOREIGN KEY(bag_id) REFERENCES learning_bags(id), FOREIGN KEY(file_id) REFERENCES files(id));
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(40) PRIMARY KEY, student_id VARCHAR(40) NOT NULL, course_id VARCHAR(40) NOT NULL, amount INTEGER NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(30) NOT NULL, provider_id VARCHAR(100) UNIQUE, checkout_url TEXT, expires_at VARCHAR(30) NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, paid_at VARCHAR(30), failure_code VARCHAR(100), FOREIGN KEY(student_id) REFERENCES users(id), FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS provider_events (id VARCHAR(64) PRIMARY KEY, provider VARCHAR(30) NOT NULL, event_type VARCHAR(100) NOT NULL, entity_id VARCHAR(100), created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS guardian_preferences (student_id VARCHAR(40) PRIMARY KEY, sms_enabled INTEGER NOT NULL DEFAULT 0, consent_at VARCHAR(30), updated_by VARCHAR(40) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(student_id) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notification_outbox (id VARCHAR(40) PRIMARY KEY, dedupe_key VARCHAR(150) NOT NULL UNIQUE, student_id VARCHAR(40) NOT NULL, class_id VARCHAR(40) NOT NULL, kind VARCHAR(30) NOT NULL, recipient TEXT NOT NULL, body TEXT NOT NULL, status VARCHAR(30) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at VARCHAR(30) NOT NULL, locked_until VARCHAR(30), lock_token VARCHAR(40), provider_id VARCHAR(100), error_code VARCHAR(100), created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(student_id) REFERENCES users(id), FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS zoom_meetings (class_id VARCHAR(40) PRIMARY KEY, meeting_id VARCHAR(100) UNIQUE, host_id VARCHAR(190) NOT NULL, status VARCHAR(30) NOT NULL, join_url TEXT, last_error VARCHAR(100), created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS zoom_presence (id VARCHAR(64) PRIMARY KEY, class_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, joined_at VARCHAR(30) NOT NULL, left_at VARCHAR(30), source VARCHAR(30) NOT NULL, FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS video_assets (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, lesson_id VARCHAR(40) UNIQUE, provider_id VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, status VARCHAR(30) NOT NULL, bytes BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(lesson_id) REFERENCES lessons(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS course_commerce_open ON course_commerce(enrollment_open);
CREATE INDEX IF NOT EXISTS bag_items_bag ON bag_items(bag_id,sort_order);
CREATE INDEX IF NOT EXISTS learning_bags_course ON learning_bags(course_id);
CREATE INDEX IF NOT EXISTS orders_student ON orders(student_id,created_at);
CREATE INDEX IF NOT EXISTS orders_course_status ON orders(course_id,status,expires_at);
CREATE INDEX IF NOT EXISTS outbox_due ON notification_outbox(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS outbox_student ON notification_outbox(student_id,created_at);
CREATE INDEX IF NOT EXISTS presence_class ON zoom_presence(class_id,student_id);
CREATE INDEX IF NOT EXISTS videos_course ON video_assets(course_id,created_at);
CREATE INDEX IF NOT EXISTS attendance_student ON attendance(student_id,class_id);
CREATE INDEX IF NOT EXISTS attendance_class_status ON attendance(class_id,status);
CREATE INDEX IF NOT EXISTS attempts_student_quiz ON attempts(student_id,quiz_id,submitted_at);
CREATE INDEX IF NOT EXISTS submissions_student ON submissions(student_id,assignment_id);
CREATE INDEX IF NOT EXISTS files_student ON files(student_id,purpose);
CREATE INDEX IF NOT EXISTS profiles_birth ON profiles(birth_date);
CREATE TABLE IF NOT EXISTS storage_locks (id VARCHAR(40) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS upload_reservations (id VARCHAR(40) PRIMARY KEY, bytes BIGINT NOT NULL, expires_at VARCHAR(30) NOT NULL);
CREATE INDEX IF NOT EXISTS uploads_expires ON upload_reservations(expires_at);
